-- 自动驾驶任务执行审计平台：H2(MODE=MySQL) 建表脚本
-- 时间列统一使用 BIGINT 存储 epoch 毫秒；状态为枚举字符串
-- SHA-256 摘要固定 64 位十六进制；相对路径使用正斜杠

CREATE TABLE IF NOT EXISTS audit_task (
    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
    task_code       VARCHAR(64)  NOT NULL,
    request_id      VARCHAR(128),
    status          VARCHAR(16)  NOT NULL,
    code_version    VARCHAR(256) NOT NULL,
    config_version  VARCHAR(256) NOT NULL,
    map_version     VARCHAR(256) NOT NULL,
    rosbag_version  VARCHAR(256) NOT NULL,
    seed            BIGINT       NOT NULL,
    fail_stage      VARCHAR(32),
    fail_times      INT          NOT NULL DEFAULT 0,
    interrupt_after VARCHAR(32),
    result_hash     VARCHAR(64),
    error_message   CLOB,
    started_at      BIGINT,
    finished_at     BIGINT,
    created_at      BIGINT       NOT NULL,
    updated_at      BIGINT       NOT NULL,
    CONSTRAINT uk_task_request UNIQUE (request_id)
);
COMMENT ON TABLE audit_task IS '审计任务主表：记录绑定版本、种子、整体状态与结果哈希';
COMMENT ON COLUMN audit_task.task_code IS '任务业务编码（调用方给定）';
COMMENT ON COLUMN audit_task.request_id IS '幂等请求ID；为空表示未启用幂等，同键同参重放、同键异参409';
COMMENT ON COLUMN audit_task.status IS '任务状态：PENDING/RUNNING/SUCCESS/FAILED/INTERRUPTED';
COMMENT ON COLUMN audit_task.code_version IS '感知/规划等代码版本摘要，必填';
COMMENT ON COLUMN audit_task.config_version IS '参数配置版本摘要，必填';
COMMENT ON COLUMN audit_task.map_version IS '地图版本摘要，必填';
COMMENT ON COLUMN audit_task.rosbag_version IS '输入 rosbag 内容摘要，必填';
COMMENT ON COLUMN audit_task.seed IS '随机种子（整数），确定性重放依据';
COMMENT ON COLUMN audit_task.fail_stage IS '模拟注入：失败阶段名，空表示不注入';
COMMENT ON COLUMN audit_task.fail_times IS '模拟注入：该阶段前 N 次执行失败，恢复后成功';
COMMENT ON COLUMN audit_task.interrupt_after IS '模拟注入：该阶段成功检查点之后中断任务，空表示不注入';
COMMENT ON COLUMN audit_task.result_hash IS '阶段摘要规范化后的 SHA-256，相同绑定与种子重放必须一致';
COMMENT ON COLUMN audit_task.error_message IS '失败或中断原因文本';
COMMENT ON COLUMN audit_task.started_at IS '首次开始执行时间，epoch 毫秒，UTC 时钟';
COMMENT ON COLUMN audit_task.finished_at IS '进入终态（成功/失败/中断）时间，epoch 毫秒';

CREATE TABLE IF NOT EXISTS task_stage (
    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
    task_id         BIGINT       NOT NULL,
    stage           VARCHAR(32)  NOT NULL,
    seq_no          INT          NOT NULL,
    status          VARCHAR(16)  NOT NULL,
    attempt         INT          NOT NULL DEFAULT 0,
    started_at      BIGINT,
    finished_at     BIGINT,
    metrics_json    CLOB,
    error_message   CLOB,
    artifact_path   VARCHAR(512),
    artifact_sha256 VARCHAR(64),
    replay_command  VARCHAR(2048),
    CONSTRAINT fk_stage_task FOREIGN KEY (task_id) REFERENCES audit_task (id),
    CONSTRAINT uk_stage_task UNIQUE (task_id, stage)
);
COMMENT ON TABLE task_stage IS '任务阶段执行记录：每个阶段一行，按 seq_no 依赖顺序执行';
COMMENT ON COLUMN task_stage.stage IS '阶段名：PERCEPTION/LOCALIZATION/PLANNING/CONTROL';
COMMENT ON COLUMN task_stage.seq_no IS '阶段依赖顺序，0 起始，禁止跳阶段';
COMMENT ON COLUMN task_stage.status IS '阶段状态：PENDING/RUNNING/SUCCESS/FAILED/INTERRUPTED';
COMMENT ON COLUMN task_stage.attempt IS '该阶段累计执行次数（恢复重跑会递增）';
COMMENT ON COLUMN task_stage.metrics_json IS '关键指标 JSON，键为指标名、值为数值，失败时可能为空';
COMMENT ON COLUMN task_stage.artifact_path IS '阶段产物相对路径（相对产物根目录）';
COMMENT ON COLUMN task_stage.artifact_sha256 IS '阶段产物文件实际 SHA-256';
COMMENT ON COLUMN task_stage.replay_command IS '可重放命令（含绑定版本、种子与上游摘要）';

CREATE TABLE IF NOT EXISTS stage_checkpoint (
    id                   BIGINT AUTO_INCREMENT PRIMARY KEY,
    task_id              BIGINT       NOT NULL,
    stage                VARCHAR(32)  NOT NULL,
    checkpoint_seq       INT          NOT NULL,
    code_version         VARCHAR(256) NOT NULL,
    config_version       VARCHAR(256) NOT NULL,
    map_version          VARCHAR(256) NOT NULL,
    rosbag_version       VARCHAR(256) NOT NULL,
    seed                 BIGINT       NOT NULL,
    upstream_digests_json CLOB       NOT NULL,
    stage_output_digest  VARCHAR(64)  NOT NULL,
    artifact_path        VARCHAR(512),
    artifact_sha256      VARCHAR(64),
    metrics_json         CLOB,
    replay_command       VARCHAR(2048),
    created_at           BIGINT       NOT NULL,
    CONSTRAINT fk_cp_task FOREIGN KEY (task_id) REFERENCES audit_task (id),
    CONSTRAINT uk_cp UNIQUE (task_id, stage, checkpoint_seq)
);
COMMENT ON TABLE stage_checkpoint IS '成功检查点：保存绑定版本、上游产物摘要链与阶段输出';
COMMENT ON COLUMN stage_checkpoint.checkpoint_seq IS '检查点序号，等于阶段 seq_no';
COMMENT ON COLUMN stage_checkpoint.upstream_digests_json IS '全部上游阶段产物摘要 JSON（阶段名->SHA-256）';
COMMENT ON COLUMN stage_checkpoint.stage_output_digest IS '本阶段输出摘要，等于产物 SHA-256';
COMMENT ON COLUMN stage_checkpoint.created_at IS '检查点落库时间，epoch 毫秒';

CREATE TABLE IF NOT EXISTS request_record (
    request_id    VARCHAR(128) PRIMARY KEY,
    task_id       BIGINT      NOT NULL,
    request_hash  VARCHAR(64) NOT NULL,
    request_json  CLOB        NOT NULL,
    created_at    BIGINT      NOT NULL
);
COMMENT ON TABLE request_record IS '幂等请求记录：requestId 唯一，保存规范化参数哈希';
COMMENT ON COLUMN request_record.request_hash IS '不含 requestId 的规范化创建参数 SHA-256';
COMMENT ON COLUMN request_record.task_id IS '该请求首次成功落库对应的任务ID';
